SELECT src, COUNT(*) AS pairs, SUM(me) AS me_pairs, SUM(me AND enc >= 10000000000) AS me_silent_pairs, SUM(CASE WHEN me THEN enc / 10000000000 ELSE 0 END) AS me_lots, SUM(me AND neur AND enc >= 10000000000) AS me_neur_pairs, SUM(CASE WHEN me AND neur THEN enc / 10000000000 ELSE 0 END) AS me_lots_neur, SUM(CASE WHEN me THEN (enc / 100000) % 100000 ELSE 0 END) AS me_lots_cov15, SUM(CASE WHEN me AND neur THEN (enc / 100000) % 100000 ELSE 0 END) AS me_lots_neur_cov15, SUM(CASE WHEN me AND NOT neur THEN (enc / 100000) % 100000 ELSE 0 END) AS me_lots_eur_cov15, SUM(CASE WHEN me THEN enc % 100000 ELSE 0 END) AS me_lots_covany, SUM(CASE WHEN me AND NOT neur THEN enc % 100000 ELSE 0 END) AS me_lots_eur_covany FROM (SELECT (SELECT t.source FROM tenders t WHERE t.id = b.tender_id) AS src, (SELECT COALESCE(COUNT(*) * 10000000000 + SUM(EXISTS (SELECT 1 FROM changes c2 WHERE c2.entity_kind = 'lot' AND c2.entity_id = lb.lot_id AND c2.version_seq IS NULL AND c2.op = 'changed' AND c2.changed_at >= 1792454400 AND c2.changed_at < 1792540800)) * 100000 + SUM(EXISTS (SELECT 1 FROM changes c3 WHERE c3.entity_kind = 'lot' AND c3.entity_id = lb.lot_id AND (c3.version_seq > b.seq OR (c3.version_seq IS NULL AND c3.changed_at >= 1792454400)))), 0) FROM tender_version_lots lb WHERE lb.tender_id = b.tender_id AND lb.seq = b.seq AND EXISTS (SELECT 1 FROM tender_version_lots la WHERE la.tender_id = b.tender_id AND la.seq = b.seq - 1 AND la.lot_id = lb.lot_id) AND NOT EXISTS (SELECT 1 FROM changes c WHERE c.entity_kind = 'lot' AND c.entity_id = lb.lot_id AND c.version_seq = b.seq)) AS enc, EXISTS (SELECT 1 FROM tender_version_amounts y WHERE y.tender_id = b.tender_id AND y.seq = b.seq AND y.currency <> 'EUR' AND y.eur_cents IS NOT NULL) AS neur, (SELECT MAX(x.eur_cents) FROM tender_version_amounts x WHERE x.tender_id = b.tender_id AND x.seq = b.seq AND x.quality IS NULL AND x.field NOT IN ('result_framework_maximum', 'result_framework_reestimate') AND x.eur_cents BETWEEN 1 AND 10000000000000) IS NOT (SELECT MAX(x.eur_cents) FROM tender_version_amounts x WHERE x.tender_id = b.tender_id AND x.seq = b.seq - 1 AND x.quality IS NULL AND x.field NOT IN ('result_framework_maximum', 'result_framework_reestimate') AND x.eur_cents BETWEEN 1 AND 10000000000000) AS me FROM tender_versions b WHERE b.published_at >= 1792368000 AND b.published_at < 1792454400 AND b.seq > 1) GROUP BY src
